/// The one rule that turns the lit panel shader into the unlit one, shared by
/// `tool/generate_unlit_panel_material.dart`, which writes the file, and
/// `test/decoration_material_test.dart`, which checks that the file on disk
/// is still what the rule produces.
library;

/// The header the generated material opens with.
const String unlitPanelMaterialHeader = '''
// GENERATED from box_decoration3d.fmat by
// tool/generate_unlit_panel_material.dart. Do not edit this file: edit the
// lit one and run the tool, and test/decoration_material_test.dart fails
// until you do.
//
// The same panel with `shading_model: unlit`: no scene lighting on it, so
// with linear tone mapping its colour is the colour it is given. It costs a
// fraction of the lit one to draw: on the Mali GPUs the first outside
// application ran on, the lighting was about three quarters of the frame.
// See PanelShading3d and docs/performance.md.

''';

/// [lit] with its material name and shading model swapped for the unlit
/// ones, under [unlitPanelMaterialHeader].
///
/// Throws when either line is not found, so a reworded header in the lit
/// shader fails loudly instead of producing a second lit material.
String unlitPanelMaterialFrom(String lit) {
  const litName = '  name: "BoxDecoration3d",\n';
  const unlitName = '  name: "BoxDecoration3dUnlit",\n';
  const litShading = '  shading_model: lit,\n';
  const unlitShading = '  shading_model: unlit,\n';
  for (final line in [litName, litShading]) {
    if (!lit.contains(line)) {
      throw StateError('box_decoration3d.fmat no longer contains `$line`');
    }
  }
  return unlitPanelMaterialHeader +
      lit
          .replaceFirst(litName, unlitName)
          .replaceFirst(litShading, unlitShading);
}
